import React, { useState, useEffect } from 'react';
import { adminService } from '../services/api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';
import { 
  Building2, 
  Users, 
  PawPrint, 
  Droplets,
  UserX,
  UserCheck,
  Search,
  RefreshCw,
  ShieldCheck,
  Power,
  X,
  Phone,
  Mail,
  MapPin,
  Calendar
} from 'lucide-react';

export default function AdminPage() {
  const { user: currentUser } = useAuth();
  const [stats, setStats] = useState({ farms: 0, users: 0, animals: 0, milkRecords: 0 });
  const [farms, setFarms] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [activeTab, setActiveTab] = useState('users'); // 'users' or 'farms'
  const [searchQuery, setSearchQuery] = useState('');
  const [actionLoadingId, setActionLoadingId] = useState(null);

  useEffect(() => {
    fetchAdminData();
  }, []);

  const fetchAdminData = async (isManualRefresh = false) => {
    if (isManualRefresh) {
      setRefreshing(true);
    } else {
      setLoading(true);
    }
    try {
      const [statsResult, farmsResult, usersResult] = await Promise.allSettled([
        adminService.stats(),
        adminService.listFarms(),
        adminService.listUsers()
      ]);

      if (statsResult.status === 'fulfilled' && statsResult.value.data?.stats) {
        setStats(statsResult.value.data.stats);
      }
      if (farmsResult.status === 'fulfilled' && farmsResult.value.data?.farms) {
        setFarms(farmsResult.value.data.farms);
      }
      if (usersResult.status === 'fulfilled' && usersResult.value.data?.users) {
        setUsers(usersResult.value.data.users);
      }

      const rejected = [statsResult, farmsResult, usersResult].filter(r => r.status === 'rejected');
      if (rejected.length > 0) {
        const forbidden = rejected.find(r => r.reason?.response?.status === 403);
        if (forbidden) {
          toast.error(forbidden.reason?.response?.data?.error || 'Yetkisiz erişim: Yönetici yetkisi gereklidir.');
        } else {
          toast.error(rejected[0]?.reason?.response?.data?.error || 'Bazı admin verileri yüklenemedi.');
        }
      } else if (isManualRefresh) {
        toast.success('Admin verileri başarıyla güncellendi.');
      }
    } catch (err) {
      console.error(err);
      toast.error(err.response?.data?.error || 'Admin verileri yüklenirken bir hata oluştu.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleToggleUserStatus = async (userId, currentStatus) => {
    if (Number(userId) === Number(currentUser?.id)) {
      toast.error('Kendi hesabınızı askıya alamazsınız.');
      return;
    }
    const nextStatus = currentStatus === 'active' ? 'suspended' : 'active';
    setActionLoadingId(`user-${userId}`);
    
    try {
      await adminService.toggleUserStatus(userId, nextStatus);
      toast.success(`Kullanıcı başarıyla ${nextStatus === 'active' ? 'aktifleştirildi' : 'askıya alındı'}.`);
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: nextStatus } : u));
      
      const statsRes = await adminService.stats().catch(() => null);
      if (statsRes?.data?.stats) {
        setStats(statsRes.data.stats);
      }
    } catch (err) {
      console.error(err);
      toast.error(err.response?.data?.error || 'Kullanıcı durumu güncellenemedi.');
    } finally {
      setActionLoadingId(null);
    }
  };

  const handleToggleFarmStatus = async (farmId, currentStatus) => {
    const nextStatus = currentStatus === 'active' ? 'expired' : 'active';
    setActionLoadingId(`farm-${farmId}`);
    
    try {
      await adminService.toggleFarmStatus(farmId, nextStatus);
      toast.success(`Çiftlik aboneliği başarıyla ${nextStatus === 'active' ? 'aktifleştirildi' : 'pasife alındı'}.`);
      setFarms(prev => prev.map(f => f.id === farmId ? { ...f, subscription_status: nextStatus } : f));
      
      const statsRes = await adminService.stats().catch(() => null);
      if (statsRes?.data?.stats) {
        setStats(statsRes.data.stats);
      }
    } catch (err) {
      console.error(err);
      toast.error(err.response?.data?.error || 'Çiftlik durumu güncellenemedi.');
    } finally {
      setActionLoadingId(null);
    }
  };

  const normalizeText = (text) => (text || '').toLocaleLowerCase('tr-TR').trim();
  const query = normalizeText(searchQuery);

  const getRoleLabel = (role) => {
    switch (role) {
      case 'admin': return 'Süper Yönetici';
      case 'owner': return 'Çiftlik Sahibi';
      case 'veterinarian': return 'Veteriner Hekim';
      case 'staff': return 'Personel';
      case 'viewer': return 'Gözlemci';
      default: return role || 'Kullanıcı';
    }
  };

  const getLicenseLabel = (type) => {
    switch (type) {
      case 'professional': return 'Profesyonel';
      case 'enterprise': return 'Kurumsal';
      case 'license': return 'Lisanslı';
      case 'free': return 'Standart';
      default: return type || 'Standart';
    }
  };

  const filteredUsers = users.filter(u => {
    if (!query) return true;
    const nameMatch = normalizeText(u.full_name).includes(query);
    const emailMatch = normalizeText(u.email).includes(query);
    const farmMatch = normalizeText(u.farm?.name).includes(query);
    const phoneMatch = normalizeText(u.phone).includes(query);
    const roleMatch = normalizeText(getRoleLabel(u.role)).includes(query) || normalizeText(u.role).includes(query);
    const statusMatch = (u.status === 'active' && 'aktif'.includes(query)) || (u.status !== 'active' && ('askıda'.includes(query) || 'pasif'.includes(query)));
    return nameMatch || emailMatch || farmMatch || phoneMatch || roleMatch || statusMatch;
  });

  const filteredFarms = farms.filter(f => {
    if (!query) return true;
    const nameMatch = normalizeText(f.name).includes(query);
    const emailMatch = normalizeText(f.email).includes(query);
    const locMatch = normalizeText(f.location).includes(query);
    const phoneMatch = normalizeText(f.phone).includes(query);
    const regMatch = normalizeText(f.registration_number).includes(query);
    const licenseMatch = normalizeText(getLicenseLabel(f.license_type)).includes(query);
    const statusMatch = (f.subscription_status === 'active' && 'aktif'.includes(query)) || (f.subscription_status !== 'active' && ('pasif'.includes(query) || 'süresi dolmuş'.includes(query)));
    return nameMatch || emailMatch || locMatch || phoneMatch || regMatch || licenseMatch || statusMatch;
  });

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[450px] gap-4">
        <div className="w-12 h-12 border-4 border-teal-600 border-t-transparent rounded-full animate-spin" />
        <p className="text-sm font-semibold text-slate-500">Admin paneli verileri yükleniyor...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <div className="flex items-center gap-2.5">
            <h1 className="text-3xl font-black text-slate-900 tracking-tight">Sistem Yönetici Paneli</h1>
            <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-bold bg-teal-100 text-teal-800">
              <ShieldCheck className="w-3.5 h-3.5" />
              Süper Admin
            </span>
          </div>
          <p className="text-sm text-slate-500 font-medium mt-1">
            Tüm çiftliklerin, kullanıcıların ve genel platform durumunun merkezi denetimi
          </p>
        </div>

        <button
          onClick={() => fetchAdminData(true)}
          disabled={refreshing}
          className="inline-flex items-center gap-2 px-4 py-2.5 rounded-2xl bg-white border border-slate-200/80 text-slate-700 hover:text-slate-950 hover:bg-slate-50 font-bold text-xs shadow-sm transition-all active:scale-95 disabled:opacity-60 self-start sm:self-auto"
        >
          <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin text-teal-600' : 'text-slate-500'}`} />
          {refreshing ? 'Yenileniyor...' : 'Verileri Yenile'}
        </button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Kayıtlı Çiftlikler', value: stats.farms, icon: Building2, color: 'from-teal-500 to-emerald-600', shadow: 'shadow-teal-500/10' },
          { label: 'Toplam Kullanıcılar', value: stats.users, icon: Users, color: 'from-blue-500 to-indigo-600', shadow: 'shadow-blue-500/10' },
          { label: 'Toplam Hayvan', value: stats.animals, icon: PawPrint, color: 'from-amber-500 to-orange-500', shadow: 'shadow-amber-500/10' },
          { label: 'Süt Sağım Kayıtları', value: stats.milkRecords, icon: Droplets, color: 'from-sky-500 to-blue-600', shadow: 'shadow-sky-500/10' },
        ].map((stat, i) => (
          <div key={i} className={`bg-white rounded-3xl p-6 border border-slate-100 shadow-xl ${stat.shadow} flex items-center justify-between`}>
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-950 mt-1">{stat.value?.toLocaleString('tr-TR') ?? 0}</h3>
            </div>
            <div className={`p-4 rounded-2xl bg-gradient-to-br ${stat.color} text-white shadow-md`}>
              <stat.icon className="w-6 h-6" />
            </div>
          </div>
        ))}
      </div>

      {/* Main Content Card */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden">
        {/* Tab Selector & Search */}
        <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex gap-2 p-1.5 bg-slate-50 rounded-2xl w-fit">
            <button 
              onClick={() => { setActiveTab('users'); setSearchQuery(''); }}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold tracking-tight transition-all ${
                activeTab === 'users' 
                  ? 'bg-white text-slate-900 shadow-md shadow-slate-900/5' 
                  : 'text-slate-500 hover:text-slate-900'
              }`}
            >
              <span>Kullanıcı Yönetimi</span>
              <span className={`px-2 py-0.5 rounded-lg text-xs font-black ${
                activeTab === 'users' ? 'bg-teal-50 text-teal-700' : 'bg-slate-200/60 text-slate-600'
              }`}>
                {filteredUsers.length}
              </span>
            </button>
            <button 
              onClick={() => { setActiveTab('farms'); setSearchQuery(''); }}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold tracking-tight transition-all ${
                activeTab === 'farms' 
                  ? 'bg-white text-slate-900 shadow-md shadow-slate-900/5' 
                  : 'text-slate-500 hover:text-slate-900'
              }`}
            >
              <span>Çiftlik Kayıtları</span>
              <span className={`px-2 py-0.5 rounded-lg text-xs font-black ${
                activeTab === 'farms' ? 'bg-teal-50 text-teal-700' : 'bg-slate-200/60 text-slate-600'
              }`}>
                {filteredFarms.length}
              </span>
            </button>
          </div>

          <div className="relative max-w-md w-full">
            <Search className="w-4 h-4 text-slate-400 absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none" />
            <input 
              type="text" 
              placeholder={`${activeTab === 'users' ? 'İsim, e-posta, telefon, çiftlik veya rol' : 'Çiftlik adı, lokasyon, e-posta'} ara...`}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-11 pr-10 py-3 bg-slate-50 border border-slate-200/60 rounded-2xl text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20 focus:border-teal-500 transition-all font-medium"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-400 hover:text-slate-600 rounded-lg"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>

        {/* Tab Panels */}
        <div className="overflow-x-auto">
          {activeTab === 'users' ? (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                  <th className="py-4 px-6">Ad Soyad / İletişim</th>
                  <th className="py-4 px-6">Bağlı Çiftlik</th>
                  <th className="py-4 px-6">Rol</th>
                  <th className="py-4 px-6">Kayıt Tarihi</th>
                  <th className="py-4 px-6">Durum</th>
                  <th className="py-4 px-6 text-right">İşlemler</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100/50">
                {filteredUsers.length > 0 ? (
                  filteredUsers.map(user => {
                    const isSelf = Number(user.id) === Number(currentUser?.id);
                    const isBusy = actionLoadingId === `user-${user.id}`;

                    return (
                      <tr key={user.id} className="hover:bg-slate-50/40 transition-colors font-medium text-sm text-slate-600">
                        <td className="py-4 px-6">
                          <div>
                            <div className="flex items-center gap-2">
                              <p className="font-bold text-slate-900">{user.full_name}</p>
                              {isSelf && (
                                <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-indigo-50 text-indigo-700">
                                  Siz
                                </span>
                              )}
                            </div>
                            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-0.5 text-xs text-slate-400 font-medium">
                              <span className="flex items-center gap-1">
                                <Mail className="w-3 h-3 text-slate-400" />
                                {user.email}
                              </span>
                              {user.phone && (
                                <span className="flex items-center gap-1 text-slate-400">
                                  <Phone className="w-3 h-3" />
                                  {user.phone}
                                </span>
                              )}
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-6">
                          <div className="flex items-center gap-1.5 font-bold text-slate-800">
                            <Building2 className="w-4 h-4 text-slate-400 shrink-0" />
                            <span>{user.farm?.name || 'Bağlı Çiftlik Yok'}</span>
                          </div>
                        </td>
                        <td className="py-4 px-6">
                          <span className={`px-2.5 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${
                            user.role === 'owner' ? 'bg-teal-50 text-teal-700' :
                            user.role === 'admin' ? 'bg-indigo-50 text-indigo-700' :
                            user.role === 'veterinarian' ? 'bg-sky-50 text-sky-700' : 'bg-slate-100 text-slate-700'
                          }`}>
                            {getRoleLabel(user.role)}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-xs text-slate-500">
                          <div className="flex items-center gap-1.5">
                            <Calendar className="w-3.5 h-3.5 text-slate-400" />
                            <span>{new Date(user.created_at || user.createdAt).toLocaleDateString('tr-TR')}</span>
                          </div>
                        </td>
                        <td className="py-4 px-6">
                          <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${
                            user.status === 'active' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
                          }`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${user.status === 'active' ? 'bg-green-600' : 'bg-red-600'}`} />
                            {user.status === 'active' ? 'Aktif' : 'Askıda'}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-right">
                          {isSelf ? (
                            <span className="text-xs text-slate-400 font-semibold italic">
                              Mevcut Oturum
                            </span>
                          ) : (
                            <button
                              onClick={() => handleToggleUserStatus(user.id, user.status)}
                              disabled={isBusy}
                              className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-black transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:pointer-events-none ${
                                user.status === 'active' 
                                  ? 'bg-red-50 text-red-600 hover:bg-red-100' 
                                  : 'bg-green-50 text-green-600 hover:bg-green-100'
                              }`}
                            >
                              {isBusy ? (
                                <div className="w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full animate-spin" />
                              ) : user.status === 'active' ? (
                                <>
                                  <UserX className="w-3.5 h-3.5" />
                                  Askıya Al
                                </>
                              ) : (
                                <>
                                  <UserCheck className="w-3.5 h-3.5" />
                                  Aktifleştir
                                </>
                              )}
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan="6" className="py-12 text-center text-slate-400 font-medium">
                      <Users className="w-8 h-8 text-slate-300 mx-auto mb-2" />
                      Aranan kriterlere uygun kullanıcı bulunamadı.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          ) : (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                  <th className="py-4 px-6">Çiftlik Adı / İletişim</th>
                  <th className="py-4 px-6">Lokasyon</th>
                  <th className="py-4 px-6">Lisans Türü</th>
                  <th className="py-4 px-6">Kayıt Tarihi</th>
                  <th className="py-4 px-6">Abonelik Durumu</th>
                  <th className="py-4 px-6 text-right">İşlemler</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100/50">
                {filteredFarms.length > 0 ? (
                  filteredFarms.map(farm => {
                    const isBusy = actionLoadingId === `farm-${farm.id}`;
                    const isActive = farm.subscription_status === 'active';

                    return (
                      <tr key={farm.id} className="hover:bg-slate-50/40 transition-colors font-medium text-sm text-slate-600">
                        <td className="py-4 px-6">
                          <div>
                            <p className="font-bold text-slate-900">{farm.name}</p>
                            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-0.5 text-xs text-slate-400 font-medium">
                              <span className="flex items-center gap-1">
                                <Mail className="w-3 h-3 text-slate-400" />
                                {farm.email}
                              </span>
                              {farm.phone && (
                                <span className="flex items-center gap-1">
                                  <Phone className="w-3 h-3 text-slate-400" />
                                  {farm.phone}
                                </span>
                              )}
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-6 font-bold text-slate-700">
                          <div className="flex items-center gap-1.5">
                            <MapPin className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                            <span>{farm.location || 'Belirtilmemiş'}</span>
                          </div>
                        </td>
                        <td className="py-4 px-6">
                          <span className={`px-2.5 py-1 rounded-lg text-xs font-bold uppercase tracking-wider ${
                            farm.license_type === 'professional' ? 'bg-amber-50 text-amber-700' :
                            farm.license_type === 'enterprise' ? 'bg-purple-50 text-purple-700' :
                            'bg-slate-100 text-slate-700'
                          }`}>
                            {getLicenseLabel(farm.license_type)}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-xs text-slate-500">
                          <div className="flex items-center gap-1.5">
                            <Calendar className="w-3.5 h-3.5 text-slate-400" />
                            <span>{new Date(farm.created_at || farm.createdAt).toLocaleDateString('tr-TR')}</span>
                          </div>
                        </td>
                        <td className="py-4 px-6">
                          <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${
                            isActive ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
                          }`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${isActive ? 'bg-green-600' : 'bg-red-600'}`} />
                            {isActive ? 'Aktif' : 'Pasif / Donduruldu'}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-right">
                          <button
                            onClick={() => handleToggleFarmStatus(farm.id, farm.subscription_status)}
                            disabled={isBusy}
                            className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-black transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:pointer-events-none ${
                              isActive 
                                ? 'bg-red-50 text-red-600 hover:bg-red-100' 
                                : 'bg-green-50 text-green-600 hover:bg-green-100'
                            }`}
                          >
                            {isBusy ? (
                              <div className="w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full animate-spin" />
                            ) : isActive ? (
                              <>
                                <Power className="w-3.5 h-3.5" />
                                Pasife Al
                              </>
                            ) : (
                              <>
                                <Power className="w-3.5 h-3.5" />
                                Aktifleştir
                              </>
                            )}
                          </button>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan="6" className="py-12 text-center text-slate-400 font-medium">
                      <Building2 className="w-8 h-8 text-slate-300 mx-auto mb-2" />
                      Aranan kriterlere uygun çiftlik bulunamadı.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
